function validatePennylaneInvoice(input, now = Date.now()) {
  const reject = (error, details, statusCode = 400) => ({ accepted: false, data: {}, filter: '', customer: {}, body: { success: false, error, details }, statusCode });
  if (!input || typeof input !== 'object' || Array.isArray(input)) return reject('invalid_payload', ['A JSON object is required.']);
  if (input.send_email !== undefined && input.send_email !== false) return reject('email_not_supported', ['Omit send_email or set it to false. This workflow creates invoices without sending email.'], 422);
  const errors = [];
  if (typeof input.customer_name !== 'string' || !input.customer_name.trim()) errors.push('customer_name is required');
  if (typeof input.customer_email !== 'string' || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.customer_email)) errors.push('customer_email must be a valid email address');
  if (!Array.isArray(input.items) || !input.items.length) errors.push('items must be a nonempty array');
  else input.items.forEach((item, index) => {
    if (!item || typeof item !== 'object' || Array.isArray(item)) { errors.push('items[' + index + '] must be an object'); return; }
    if (typeof item.label !== 'string' || !item.label.trim()) errors.push('items[' + index + '].label is required');
    if (typeof item.quantity !== 'number' || !Number.isFinite(item.quantity) || item.quantity <= 0) errors.push('items[' + index + '].quantity must be a number > 0');
    if (typeof item.unit_price !== 'number' || !Number.isFinite(item.unit_price) || item.unit_price <= 0 || !/^\d+\.\d{2}$/.test(item.unit_price.toFixed(2))) errors.push('items[' + index + '].unit_price must be a positive finite number representable with two decimal places');
    if (item.vat_rate !== undefined && (typeof item.vat_rate !== 'string' || !item.vat_rate.trim())) errors.push('items[' + index + '].vat_rate must be a nonempty Pennylane VAT code');
  });
  if (input.customer_country !== undefined && (typeof input.customer_country !== 'string' || !/^[A-Z]{2}$/.test(input.customer_country))) errors.push('customer_country must be an uppercase two-letter country code');
  if (input.currency !== undefined && (typeof input.currency !== 'string' || !/^[A-Z]{3}$/.test(input.currency))) errors.push('currency must be an uppercase three-letter currency code');
  if (input.reference !== undefined && input.reference !== null && (typeof input.reference !== 'string' || !input.reference.trim())) errors.push('reference must be nonempty text when supplied');
  if (input.due_date !== undefined && (typeof input.due_date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(input.due_date) || !Number.isFinite(Date.parse(input.due_date + 'T00:00:00Z')) || new Date(input.due_date + 'T00:00:00Z').toISOString().slice(0, 10) !== input.due_date)) errors.push('due_date must be a real date in YYYY-MM-DD format');
  if (errors.length) return reject('invalid_payload', errors);
  const data = {
    customer_name: input.customer_name.trim(), customer_email: input.customer_email.toLowerCase(),
    customer_address: typeof input.customer_address === 'string' ? input.customer_address : '',
    customer_postal_code: typeof input.customer_postal_code === 'string' ? input.customer_postal_code : '00000',
    customer_city: typeof input.customer_city === 'string' ? input.customer_city : 'Non renseigné',
    customer_country: input.customer_country ?? 'FR', currency: input.currency ?? 'EUR', reference: input.reference ?? null,
    items: input.items.map(item => ({ label: item.label.trim(), quantity: item.quantity, unit_price: item.unit_price, vat_rate: item.vat_rate ?? 'FR_200' })),
    due_date: input.due_date ?? new Date(now + 30 * 86400000).toISOString().slice(0, 10), invoice_date: new Date(now).toISOString().slice(0, 10), send_email: false,
  };
  return { accepted: true, data, filter: JSON.stringify([{ field: 'emails', operator: 'in', value: [data.customer_email] }]), customer: { name: data.customer_name, emails: [data.customer_email], billing_address: { address: data.customer_address, postal_code: data.customer_postal_code, city: data.customer_city, country_alpha2: data.customer_country } }, body: {}, statusCode: 200 };
}

function authorizePennylaneInvoice({ body, headers, expectedAuthorization }) {
  const credentials = header => {
    if (typeof header !== 'string') return '';
    const match = /^ *Basic +([A-Za-z0-9+/]+={0,2}) *$/i.exec(header);
    if (!match) return '';
    const decoded = Buffer.from(match[1], 'base64').toString('utf8');
    const separator = decoded.indexOf(':');
    return separator > 0 && separator < decoded.length - 1 && !/[\r\n]/.test(decoded) ? decoded : '';
  };
  const expected = credentials(expectedAuthorization);
  if (!expected) throw new Error('Configure the protected webhook Basic authorization secret with a nonempty username and password before enabling this workflow.');
  const values = Object.entries(headers ?? {}).filter(([name]) => name.toLowerCase() === 'authorization');
  const received = values.length === 1 ? credentials(values[0][1]) : '';
  // Compare decoded username/password without returning either credential.
  let difference = received.length ^ expected.length;
  for (let index = 0; index < Math.max(received.length, expected.length); index++) difference |= (received.charCodeAt(index) || 0) ^ (expected.charCodeAt(index) || 0);
  if (difference !== 0) return { accepted: false, data: {}, filter: '', customer: {}, body: { success: false, error: 'unauthorized' }, statusCode: 401 };
  return validatePennylaneInvoice(body);
}

return [{json:validatePennylaneInvoice($input.first().json.body)}];

function pennylaneInvoiceReply({ body, statusCode, data, rejected }) {
  const headers = { 'Cache-Control': 'no-store', ...(statusCode === 401 ? { 'WWW-Authenticate': 'Basic realm="Webhook"' } : {}) };
  if (rejected) return { body, statusCode, headers };
  if (statusCode !== 201 || !body || typeof body !== 'object' || !Number.isSafeInteger(body.id) || body.id <= 0 || typeof body.invoice_number !== 'string' || !body.invoice_number.trim() || typeof body.currency_amount !== 'string' || !body.currency_amount.trim() || (body.public_file_url !== null && typeof body.public_file_url !== 'string')) throw new Error('Pennylane did not confirm a completed invoice with its documented HTTP 201 fields.');
  return { body: { success: true, invoice_id: String(body.id), invoice_number: body.invoice_number, amount: body.currency_amount, customer: data.customer_name, public_url: body.public_file_url || null, email_sent: false }, statusCode: 200, headers };
}

return [{json:pennylaneInvoiceReply({body:$json.body,statusCode:$json.statusCode,data:{},rejected:true})}];

function selectPennylaneCustomer({ body, statusCode, data }) {
  if (statusCode !== 200 || !body || typeof body !== 'object' || !Array.isArray(body.items)) throw new Error('Pennylane customer lookup did not return its documented list response.');
  if (!body.items.length) return { found: false, customerId: 0 };
  const id = body.items[0]?.id;
  if (!Number.isSafeInteger(id) || id <= 0) throw new Error('The first matching Pennylane customer has no valid integer ID.');
  const emails = body.items[0].emails;
  if (!Array.isArray(emails) || !emails.some(email => typeof email === 'string' && email.trim().toLowerCase() === data.customer_email)) throw new Error('The first returned Pennylane customer does not contain the requested email. No invoice was created.');
  return { found: true, customerId: id };
}

return [{json:selectPennylaneCustomer({...$json,data:$('Validate Invoice Request').first().json.data})}];

function buildPennylaneInvoice({ data, mode, body, statusCode, customerId }) {
  let id = customerId;
  if (mode === 'created') {
    if (statusCode !== 201 || !body || typeof body !== 'object') throw new Error('Pennylane did not confirm customer creation with HTTP 201.');
    id = body.id;
  } else if (mode !== 'existing') throw new Error('Unknown customer selection path.');
  if (!Number.isSafeInteger(id) || id <= 0) throw new Error('A valid Pennylane customer ID is required before creating an invoice.');
  const payload = {
    customer_id: id, date: data.invoice_date, deadline: data.due_date, currency: data.currency,
    invoice_lines: data.items.map(item => ({ label: item.label, quantity: item.quantity, unit: 'piece', raw_currency_unit_price: String(item.unit_price.toFixed(2)), vat_rate: item.vat_rate })), draft: false,
  };
  if (data.reference) payload.external_reference = data.reference;
  return { payload };
}

return [{json:buildPennylaneInvoice({data:$('Validate Invoice Request').first().json.data,mode:'created',body:$json.body,statusCode:$json.statusCode,customerId:0})}];

